<?php require_once '../config/auth.php';requireLogin();require_once '../config/database.php';$id=(int)$_GET['id'];$r=$conn->query("SELECT livro_id,estado FROM emprestimos WHERE id=$id")->fetch_assoc();if($r && $r['estado']==='emprestado'){$s=$conn->prepare("UPDATE emprestimos SET estado='devolvido',data_devolucao=CURDATE() WHERE id=?");$s->bind_param('i',$id);$s->execute();$s=$conn->prepare("UPDATE livros SET quantidade_disponivel=quantidade_disponivel+1 WHERE id=?");$s->bind_param('i',$r['livro_id']);$s->execute();}header('Location: index.php');exit;?>